package com.rukmini.hostel;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity {
    LinearLayout root, content, bottom; TextView title; final int PURPLE=Color.rgb(91,63,212); android.content.SharedPreferences sp;
    ArrayList<String> tenants=new ArrayList<>();
    @Override public void onCreate(Bundle b){super.onCreate(b); sp=getSharedPreferences("data",0); load(); showHome();}
    TextView tv(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.DKGRAY);t.setPadding(16,12,16,12);return t;}
    Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setBackgroundColor(PURPLE);return b;}
    void base(String heading){ root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(246,247,251));
      LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(8,8,8,8);bar.setBackgroundColor(PURPLE); TextView menu=tv("☰",25);menu.setTextColor(Color.WHITE);bar.addView(menu,new LinearLayout.LayoutParams(55,60));
      title=tv(heading,20);title.setTextColor(Color.WHITE);title.setTypeface(null,1);bar.addView(title,new LinearLayout.LayoutParams(0,60,1)); TextView bell=tv("🔔",20);bell.setTextColor(Color.WHITE);bar.addView(bell,new LinearLayout.LayoutParams(55,60)); root.addView(bar);
      ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(12,12,12,12);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
      bottom=new LinearLayout(this);bottom.setBackgroundColor(Color.WHITE);String[] n={"⌂\nHome","👥\nTenants","🛏\nRooms","₹\nPayments","•••\nMore"}; for(int i=0;i<5;i++){Button x=new Button(this);x.setText(n[i]);x.setTextSize(11);x.setTextColor(Color.DKGRAY);final int k=i;x.setOnClickListener(v->{if(k==0)showHome();else if(k==1)showTenants();else if(k==2)showRooms();else if(k==3)showPayments();else showMore();});bottom.addView(x,new LinearLayout.LayoutParams(0,70,1));}root.addView(bottom);setContentView(root); }
    TextView card(String s){TextView t=tv(s,15);t.setBackgroundColor(Color.WHITE);t.setPadding(18,18,18,18);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,6,0,6);content.addView(t,p);return t;}
    void showHome(){base("Rukmini Hostel");card("PG MANAGEMENT • Dashboard");LinearLayout grid=new LinearLayout(this);grid.setOrientation(LinearLayout.VERTICAL);content.addView(grid);String[] a={"👥 Total Tenants: "+tenants.size(),"🛏 Occupied Beds: "+Math.max(0,tenants.size()),"🟢 Available Beds: 4","💰 This Month Collection: ₹0","🔴 Pending Rent: ₹0","⚡ Pending Electricity: ₹0"};for(String s:a){TextView t=tv(s,16);t.setBackgroundColor(Color.WHITE);grid.addView(t,new LinearLayout.LayoutParams(-1,58));}card("📅 Upcoming Due Dates\nNo pending reminders yet.");Button add=btn("+  ADD TENANT");add.setOnClickListener(v->addTenant());content.addView(add,new LinearLayout.LayoutParams(-1,55));Button pay=btn("₹  ADD PAYMENT");pay.setOnClickListener(v->addPayment());content.addView(pay,new LinearLayout.LayoutParams(-1,55));}
    void showTenants(){base("Tenants");EditText search=new EditText(this);search.setHint("Search tenant...");content.addView(search,new LinearLayout.LayoutParams(-1,55));for(String s:tenants)card("👩  "+s+"\nRoom: Not assigned   •   ₹7,000 / month   ✅ Active");Button b=btn("+ ADD TENANT");b.setOnClickListener(v->addTenant());content.addView(b,new LinearLayout.LayoutParams(-1,55));}
    void addTenant(){final EditText e=new EditText(this);e.setHint("Tenant full name");new AlertDialog.Builder(this).setTitle("Add Tenant").setView(e).setMessage("Add a tenant to your PG records.").setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String n=e.getText().toString().trim();if(!n.isEmpty()){tenants.add(n);save();showTenants();}}).show();}
    void showRooms(){base("Rooms");card("🛏 Room 101     3/4 Occupied     🟢 1 Bed Available");card("🛏 Room 102     4/4 Occupied     🔴 Full");card("🛏 Room 103     2/4 Occupied     🟢 2 Beds Available");card("🛏 Room 104     1/4 Occupied     🟢 3 Beds Available");Button b=btn("+ ADD ROOM");b.setOnClickListener(v->Toast.makeText(this,"Room management is ready for the next data module.",Toast.LENGTH_SHORT).show());content.addView(b,new LinearLayout.LayoutParams(-1,55));}
    void showPayments(){base("Payments");card("💰 Payment History\nNo payments recorded yet.");Button b=btn("+ ADD PAYMENT");b.setOnClickListener(v->addPayment());content.addView(b,new LinearLayout.LayoutParams(-1,55));}
    void addPayment(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);EditText n=new EditText(this);n.setHint("Tenant name");EditText a=new EditText(this);a.setHint("Amount");a.setInputType(2);box.addView(n);box.addView(a);new AlertDialog.Builder(this).setTitle("Add Payment").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->Toast.makeText(this,"Payment saved for "+n.getText()+" • ₹"+a.getText(),Toast.LENGTH_LONG).show()).show();}
    void showMore(){base("More");String[] m={"🧾 Monthly Bills","🔔 Reminders","💸 Expenses","📊 Reports","📁 Documents","🔔 Notifications","⚙ Settings","Backup & Export Data"};for(String s:m){Button b=btn(s);content.addView(b,new LinearLayout.LayoutParams(-1,55));}}
    void load(){String raw=sp.getString("tenants","");if(!raw.isEmpty())tenants.addAll(Arrays.asList(raw.split("\\|",-1)));tenants.removeIf(x->x.isEmpty());}
    void save(){StringBuilder b=new StringBuilder();for(String s:tenants){if(b.length()>0)b.append('|');b.append(s.replace("|"," "));}sp.edit().putString("tenants",b.toString()).apply();}
}
